mapper.select:
SELECT * FROM logan_crash

    app_id=#{appId}

ORDER BY crash_time DESC LIMIT #{limit}

mapper.update:
UPDATE logan_crash_issue
SET crash_count=#{crashCount}, last_crash_time=#{lastCrashTime}, affected_devices=#{affectedDevices}
WHERE id=#{id}

UPDATE logan_crash_issue
SET status = 0, reopen_count = #{reopenCount}, last_fix_note = #{lastFixNote}
WHERE id = #{id}

mapper.select:
SELECT * FROM logan_crash_issue

    app_id=#{appId}

ORDER BY last_crash_time DESC LIMIT #{limit}

SELECT * FROM logan_crash_issue
WHERE llm_summary IS NULL AND crash_count >= 1
ORDER BY last_crash_time DESC LIMIT #{limit}

SELECT DATE_FORMAT(FROM_UNIXTIME(crash_time/1000), '%Y-%m-%d') AS d, kind, COUNT(*) AS cnt
FROM logan_crash
WHERE crash_time BETWEEN #{beginTime} AND #{endTime}
AND app_id=#{appId}
GROUP BY d, kind ORDER BY d

SELECT kind, COUNT(*) AS total, COUNT(DISTINCT fingerprint) AS issues, COUNT(DISTINCT device_id) AS devices, MAX(crash_time) AS lastCrashTime FROM logan_crash
app_id=#{appId}
GROUP BY kind

SELECT id, app_id, platform, kind, fingerprint, device_id, union_id, user_id,
       app_version, build_version, brand, model, manufacturer, sdk_int, release_ver,
       abi, signal_info, top_frames, deferred, crash_time, add_time, content_hash
FROM logan_crash
WHERE app_id=#{appId} AND fingerprint=#{fingerprint}
ORDER BY crash_time DESC LIMIT #{limit}

SELECT i.*,
       (SELECT COUNT(*) FROM logan_crash c
         WHERE c.app_id=i.app_id AND c.fingerprint=i.fingerprint
         AND c.kind=#{q.kind}
         AND c.brand LIKE CONCAT('%',#{q.brand},'%')
         AND c.model LIKE CONCAT('%',#{q.model},'%')
         AND c.device_id LIKE CONCAT('%',#{q.deviceId},'%')
         AND c.union_id LIKE CONCAT('%',#{q.unionId},'%')
         AND c.app_version=#{q.appVersion}
         AND c.build_version=#{q.buildVersion}
         AND c.crash_time >= #{q.beginTime}
         AND c.crash_time <= #{q.endTime}
         AND (c.content LIKE CONCAT('%',#{q.keyword},'%') OR c.signal_info LIKE CONCAT('%',#{q.keyword},'%') OR c.fingerprint LIKE CONCAT('%',#{q.keyword},'%'))
       ) AS filtered_crash_count,
       (SELECT COUNT(DISTINCT c.device_id) FROM logan_crash c
         WHERE c.app_id=i.app_id AND c.fingerprint=i.fingerprint
         AND c.brand LIKE CONCAT('%',#{q.brand},'%')
         AND c.model LIKE CONCAT('%',#{q.model},'%')
         AND c.device_id LIKE CONCAT('%',#{q.deviceId},'%')
         AND c.union_id LIKE CONCAT('%',#{q.unionId},'%')
         AND c.crash_time >= #{q.beginTime}
         AND c.crash_time <= #{q.endTime}
       ) AS filtered_devices
FROM logan_crash_issue i

    EXISTS (SELECT 1 FROM logan_crash c
            WHERE c.app_id=i.app_id AND c.fingerprint=i.fingerprint
            )


ORDER BY i.last_crash_time DESC
LIMIT #{q.offset}, #{q.limit}

SELECT DISTINCT CONCAT(app_version, ' (', build_version, ')') FROM logan_crash
app_id=#{appId}
ORDER BY 1 DESC LIMIT 50

SELECT DISTINCT brand, model FROM logan_crash

    app_id=#{appId}

ORDER BY brand, model LIMIT 200
